def main():
    sources = json.loads(Path("source.json").read_text())
    assert len(sources) == len(METADATA) == 14
    answer = []
    for index, (source, (reason, notes)) in enumerate(zip(sources, METADATA)):
        item = {key: source[key] for key in ("code_id", "source_id", "source_sha256", "number")}
        item.update(
            proposed_xml=Path(f"drafts/{index:02}.xml").read_text().strip(),
            reason=reason,
            review_notes=notes,
            status="rewrite_draft",
        )
        answer.append(item)
    Path("answer.json").write_text(json.dumps(answer, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()
